var CATS=["Bases & vocabulaire","Chiffrement symétrique","Chiffrement asymétrique","Hachage & signature","Certificats & protocoles","Mots de passe","OpenSSL pratique","Squid (proxy)"];
var TD_NAMES=["TD1 · Cryptographie traditionnelle","TD2 · Chiffrement moderne","TD3 · Protocoles cryptographiques","TD4 · Protocoles de sécurité"];
var Q=[
[0,`Que désigne la <b>cryptanalyse</b> ?`,["Chiffrer un message","Retrouver le clair sans connaître la clé","Générer une paire de clés","Calculer une empreinte"],1,`La cryptologie = cryptographie (chiffrer/déchiffrer) + cryptanalyse (casser sans la clé).`],
[0,`Quel service empêche l’émetteur de nier avoir envoyé un message ?`,["Confidentialité","Intégrité","Non-répudiation","Disponibilité"],2,`La non-répudiation est apportée par la signature numérique.`],
[0,`Que dit le <b>principe de Kerckhoffs</b> ?`,["L’algorithme doit rester secret","La sécurité repose uniquement sur la clé, même si l’algorithme est public","Plus la clé est courte, mieux c’est","Une clé ne doit jamais changer"],1,`On suppose que l’attaquant connaît le système de chiffrement : seul le secret de la clé compte.`],
[0,`Quelle différence entre <i>chiffrer</i> et <i>déchiffrer</i> ?`,["Aucune","Déchiffrer = retrouver le clair avec la clé ; décrypter = sans la clé","Chiffrer nécessite deux clés","Déchiffrer produit une empreinte"],1,`Déchiffrer utilise la clé. Décrypter (casser) se fait sans connaître la clé.`],
[1,`Avec le chiffre de César (K=3), <code>ZIG</code> donne :`,["CLJ","DEF","CKJ","BHF"],0,`E(K,X)=(X+K) mod 26. Z(25)+3=28 mod 26=2→C ; I(8)→L ; G(6)→J. Résultat : CLJ.`],
[1,`Combien de clés possibles pour le chiffre de César ?`,["26!","25","3","256"],1,`Clé de 1 à 25 : 25 essais suffisent. En plus, l’analyse de fréquences (Al-Kindi) casse ce chiffre.`],
[1,`Pourquoi la substitution monoalphabétique reste cassable malgré 26! clés ?`,["Elle est réversible","Les fréquences des lettres de la langue se conservent","La clé est trop courte","Elle utilise XOR"],1,`En français, E est la lettre la plus fréquente : on la repère dans le chiffré. Le vrai remède : une lettre ne doit pas toujours être chiffrée pareil (polyalphabétique, ex. Vigenère).`],
[1,`Combien de clés pour <b>100 personnes</b> en cryptographie symétrique (chacun avec chacun) ?`,["100","200","4950","9900"],2,`n(n−1)/2 = 100×99/2 = 4950. C’est la problématique de gestion/partage des clés.`],
[1,`Calcul XOR : <code>100111 ⊕ 110011</code> =`,["010100","110100","001100","101111"],0,`XOR vaut 1 si les bits diffèrent : 010100. Refaire ⊕ 110011 redonne 100111 (déchiffrement).`],
[1,`Un chiffrement de Vernam (masque jetable) est sûr si :`,["La clé est réutilisée","La clé est aussi longue que le message, aléatoire et utilisée une seule fois","La clé fait 56 bits","On utilise ECB"],1,`Contrainte principale : transmettre une clé aussi longue que le message, d’où l’usage de clés plus courtes et de générateurs pseudo-aléatoires.`],
[1,`Lequel est un chiffrement <b>par bloc</b> ?`,["RC4","A5/1","AES","E0"],2,`Par bloc : DES, 3DES, IDEA, RC5, AES, Blowfish. Par flux : RC4 (SSL, Wi-Fi), A5 (GSM), E0 (Bluetooth).`],
[1,`Quel défaut présente le mode <b>ECB</b> ?`,["Il est trop lent","Deux blocs clairs identiques donnent deux blocs chiffrés identiques","Il nécessite deux clés","Il ne chiffre que 8 bits"],1,`ECB laisse fuir des motifs. CBC enchaîne les blocs (XOR avec le chiffré précédent) et utilise un vecteur d’initialisation (IV) pour rendre chaque message unique.`],
[2,`B veut envoyer un message <b>confidentiel</b> à A. B chiffre avec :`,["La clé privée de B","La clé publique de A","La clé privée de A","La clé publique de B"],1,`Seul A possède la clé privée correspondante pour déchiffrer. Mais A ne peut pas authentifier l’émetteur.`],
[2,`Chiffrer avec sa <b>clé privée</b> apporte surtout :`,["La confidentialité","L’authentification de l’émetteur","La disponibilité","La compression"],1,`Tout le monde peut déchiffrer avec la clé publique, donc pas de secret, mais seul le propriétaire a pu produire le message.`],
[2,`RSA repose sur la difficulté de :`,["Factoriser un grand entier N=p·q","Calculer un hachage","Inverser XOR","Trouver une collision MD5"],0,`Multiplier p et q est facile, retrouver p et q à partir de N est difficile. RSA-640 a été factorisé en ~30 ans-CPU.`],
[2,`Diffie-Hellman permet de :`,["Signer un document","Convenir d’une clé secrète commune sur un canal non sûr","Hacher un mot de passe","Chiffrer un fichier de 1 Go"],1,`A envoie g^a mod p, B envoie g^b mod p ; chacun calcule K = g^(ab) mod p. Sécurité : logarithme discret.`],
[2,`Quel problème difficile fonde ECC / ECDSA ?`,["Factorisation","Logarithme discret elliptique : retrouver d tel que Q=dP","Collision de hash","Somme de contrôle"],1,`À sécurité égale, l’ECC utilise des clés beaucoup plus courtes que RSA.`],
[2,`Pourquoi utiliser un chiffrement <b>hybride</b> ?`,["L’asymétrique est lent : il sert à échanger une clé symétrique rapide","Le symétrique est incassable","Pour éviter les certificats","Pour économiser des clés publiques"],0,`Principe de TLS/HTTPS : asymétrique pour l’échange de clé, symétrique (AES) pour les données.`],
[3,`Propriétés d’une fonction de hachage :`,["Réversible, taille variable","Irréversible, sortie de taille fixe, résistante aux collisions","Réversible, taille fixe","Utilise une clé publique"],1,`« ab » et « abcdefgh » donnent des empreintes de même taille mais différentes.`],
[3,`Taille des empreintes : MD5 / SHA-1 / SHA-256 :`,["128 / 160 / 256 bits","64 / 128 / 256 bits","160 / 256 / 512 bits","128 / 128 / 256 bits"],0,`MD5 et SHA-1 sont considérés cassés (collisions) : préférer SHA-256 ou SHA-3 (Keccak).`],
[3,`Comment est calculée une <b>signature numérique</b> ?`,["Hash du message chiffré avec la clé publique du destinataire","Hash du message chiffré avec la clé privée de l’émetteur","Message chiffré avec AES","XOR du message et de la clé"],1,`s = E(PrivA, H(m)). Le récepteur déchiffre s avec PubA et compare avec H(m) recalculé.`],
[3,`La signature numérique garantit :`,["Authentification, intégrité, non-répudiation","Confidentialité uniquement","Disponibilité","Anonymat"],0,`Le message est envoyé en clair : la signature ne chiffre pas le message. Pour le secret, il faut en plus chiffrer (signer puis chiffrer).`],
[3,`Comment stocker correctement un mot de passe en base ?`,["En clair","Chiffré avec AES et la clé dans le code","Haché (avec sel et algorithme lent)","En Base64"],2,`On compare H(saisie) avec l’empreinte stockée. Le sel évite les tables précalculées.`],
[4,`Quelle attaque exploite l’échange non authentifié de clés publiques ?`,["Force brute","Man In the Middle","Fréquences","Replay hors-ligne"],1,`M envoie sa clé PubM à la place de PubB, déchiffre, relit puis rechiffre avec PubB. Parades : SAS, certificats, Web of Trust.`],
[4,`Un certificat numérique contient :`,["Seulement la clé privée","Propriétaire, clé publique, date d’expiration, émetteur et signature de la CA","Le mot de passe de l’utilisateur","Un hash du disque"],1,`La CA (tiers de confiance) signe le certificat avec <b>sa clé privée</b> ; le navigateur vérifie avec la clé publique de la CA préinstallée.`],
[4,`Dans HTTPS, une fois le certificat vérifié, le navigateur :`,["Envoie son mot de passe","Crée une clé symétrique, la chiffre avec PubSVR et l’envoie","Utilise RSA pour toute la session","Désactive le chiffrement"],1,`Puis toutes les communications sont chiffrées avec la même clé symétrique (TLS = hybride).`],
[4,`Le cadenas HTTPS prouve que :`,["Le site est honnête","Les échanges sont chiffrés et la clé publique appartient au domaine","Le site n’a aucune faille","Le site est légal"],1,`Un pirate peut aussi obtenir un certificat pour son site de phishing : cadenas ≠ site fiable.`],
[4,`Un certificat <b>auto-signé</b> est :`,["Signé par une CA publique","Signé par sa propre entité, inconnu des navigateurs par défaut","Toujours invalide","Réservé à SSH"],1,`Aussi sûr s’il est installé manuellement chez les clients, mais pas passe-partout : il déclenche l’alerte « certificat non fiable ».`],
[4,`Dans Needham-Schroeder, que servent <code>Na</code> et <code>Nb</code> ?`,["De clés publiques","De nombres aléatoires (nonces) prouvant la possession des clés privées","De hachages","De certificats"],1,`{Na.A}PubB → {Na.Nb}PubA → {Nb}PubB : chacun prouve qu’il sait déchiffrer.`],
[0,`Dans le TD1, César chiffre <code>WELCOMETOUASZ</code> avec <code>K=5</code>. Quel est le cryptogramme ?`,["BJQHTRJYTZFXE","BJQHTRJYTZFXD","BJQHTRJYTFXE","BJQHTRJYTZE FX"],0,`On applique E(x)=(x+5) mod 26 à chaque lettre : W→B, E→J, L→Q, C→H. Le résultat complet est <code>BJQHTRJYTZFXE</code>.`],
[1,`En mode ECB, deux blocs clairs identiques sont chiffrés avec la même clé. Que peut apprendre un observateur ?`,["Le fait qu’ils sont identiques, même sans connaître leur contenu","Leur contenu exact dans tous les cas","Rien : ECB randomise chaque bloc","La clé secrète"],0,`ECB chiffre chaque bloc indépendamment : un même bloc clair produit le même bloc chiffré. Les répétitions et motifs restent visibles, comme l’étudie le TD2.`],
[1,`Dans CBC, à quoi sert le vecteur d’initialisation (IV) du premier bloc ?`,["À mélanger le premier bloc clair avant son chiffrement","À remplacer la clé AES","À signer le message","À compresser le texte"],0,`Le premier bloc est combiné avec l’IV avant chiffrement. L’IV peut être transmis en clair, mais il doit respecter les exigences du mode ; pour CBC, il doit être imprévisible.`],
[1,`Pourquoi ne faut-il pas réutiliser le même couple clé-IV en AES-CBC ?`,["Des préfixes clairs identiques peuvent produire le même premier bloc chiffré","La clé est automatiquement publiée","Le second message ne peut plus être déchiffré","CBC se transforme alors en GCM"],0,`Avec le même IV et la même clé, des préfixes identiques produisent le même premier bloc chiffré. Un IV neuf et imprévisible est nécessaire pour chaque chiffrement CBC.`],
[1,`Quel avantage essentiel apporte AES-GCM par rapport à AES-CBC utilisé seul ?`,["L’authentification du message en plus du chiffrement","La suppression de toute clé","La compatibilité avec Base64","Le hachage lent des mots de passe"],0,`GCM est un mode de chiffrement authentifié : le destinataire vérifie un tag. Si le message ou le tag est modifié, la vérification échoue ; CBC seul ne fournit pas cette authentification.`],
[2,`Diffie-Hellman utilise <code>g=5</code>, <code>p=13</code>, avec les secrets <code>a=3</code> et <code>b=5</code>. Quelle clé partagée obtiennent A et B ?`,["5","8","10","12"],1,`A publie 5³ mod 13 = 8 et B publie 5⁵ mod 13 = 5. La clé commune vaut 5¹⁵ mod 13 = 8.`],
[2,`Diffie-Hellman est utilisé sans authentifier les clés publiques échangées. Quelle attaque reste possible ?`,["Un homme du milieu qui établit une clé distincte avec chaque interlocuteur","Une collision automatique dans SHA-256","Une attaque par bourrage de blocs","Une attaque par dictionnaire sur AES"],0,`Un attaquant peut intercepter et remplacer les valeurs publiques, puis établir une clé avec A et une autre avec B. Diffie-Hellman seul ne prouve pas l’identité du correspondant.`],
[2,`Un fichier est trop volumineux pour être chiffré directement par RSA. Quelle solution correspond au chiffrement hybride du TP ?`,["Chiffrer le fichier avec AES et protéger la clé AES avec la clé publique du destinataire","Découper le fichier en caractères et signer chaque lettre","Hacher le fichier puis utiliser le hash comme clé privée","Chiffrer le fichier deux fois avec la clé publique"],0,`Le chiffrement symétrique traite efficacement les données ; l’asymétrique sert à transporter ou établir la clé de session. Le destinataire récupère cette clé avec sa clé privée.`],
[3,`Après modification d’un bit d’un message signé, que doit faire la vérification de signature ?`,["Échouer, car l’empreinte recalculée ne correspond plus à la signature","Réussir, car la signature ne couvre que le nom du fichier","Déchiffrer le message avec la clé publique","Remplacer automatiquement le bit"],0,`La signature porte sur l’empreinte du message. Une modification change normalement cette empreinte et la vérification avec la clé publique échoue.`],
[4,`Dans un échange de protocole, un nonce <code>Na</code> est envoyé puis renvoyé par le correspondant. Quel est son rôle principal ?`,["Prouver que le message est récent et lié à cet échange","Remplacer le certificat","Cacher l’adresse IP","Augmenter la taille de la clé RSA"],0,`Le nonce est une valeur fraîche. Son retour correct aide à détecter le rejeu d’anciens messages et à vérifier que le correspondant participe à l’échange en cours.`],
[4,`Dans une capture TLS, où chercher le nom de domaine demandé par le client lorsqu’il est transmis ?`,["Dans l’extension SNI du Client Hello","Dans le message Finished uniquement","Dans le tag GCM","Dans le champ TCP Window"],0,`Le SNI (Server Name Indication) est une extension du Client Hello qui permet notamment au serveur de sélectionner le certificat approprié. Sa présence dépend de la capture analysée.`],
[4,`Pour déchiffrer dans Wireshark le trafic TLS de son navigateur de test, quelle démarche du TP2 convient ?`,["Configurer SSLKEYLOGFILE avant de lancer le navigateur, puis indiquer le fichier dans les préférences TLS de Wireshark","Exporter la clé privée du site depuis le navigateur","Remplacer la CA système par le certificat serveur","Désactiver TLS dans Wireshark"],0,`Le navigateur journalise les secrets de session dans le fichier configuré ; Wireshark utilise ce fichier pour décoder la capture. Il faut protéger ce fichier, car il permet de déchiffrer les sessions correspondantes.`],
[5,`Une base contient des empreintes MD5 de mots de passe, sans sel. Comment une attaque par dictionnaire retrouve-t-elle certains mots ?`,["L’attaquant hache des mots probables et compare leurs empreintes à celles volées","MD5 est réversible mathématiquement","Les empreintes contiennent toujours le mot de passe en clair","Le nom du compte révèle automatiquement le sel"],0,`Le TP3 illustre la comparaison avec des empreintes précalculées. Un hash n’est pas déchiffré : les candidats sont hachés puis comparés. MD5 est trop rapide pour stocker des mots de passe.`],
[5,`Quel changement rend une attaque par tables précalculées nettement moins efficace pour les mots de passe ?`,["Un sel unique par mot de passe et une fonction dédiée lente, comme Argon2id","Encoder l’empreinte en Base64","Remplacer MD5 par SHA-256 sans autre changement","Rendre le nom d’utilisateur secret"],0,`Un sel unique empêche de réutiliser directement une table commune ; une fonction de dérivation lente augmente le coût de chaque essai. Argon2id, scrypt, bcrypt ou PBKDF2 sont conçus pour cet usage.`],
[6,`Dans <code>openssl enc</code>, quelle option fournit explicitement la clé et laquelle fournit l’IV ?`,["<code>-K</code> pour la clé et <code>-iv</code> pour l’IV","<code>-in</code> pour la clé et <code>-out</code> pour l’IV","<code>-base64</code> pour la clé et <code>-d</code> pour l’IV","<code>-salt</code> pour la clé et <code>-e</code> pour l’IV"],0,`Le TP1-a utilise <code>-K</code> suivi de la clé hexadécimale et <code>-iv</code> suivi du vecteur hexadécimal. Les valeurs doivent respecter les longueurs attendues par l’algorithme et le mode.`],
[6,`Que fait <code>openssl enc -d -base64 -in entree -out sortie</code> ?`,["Décode une représentation Base64, sans assurer de confidentialité","Déchiffre AES avec une clé implicite","Calcule une empreinte SHA-256","Vérifie une signature RSA"],0,`Base64 est un encodage, pas un chiffrement : le décodage ne nécessite aucun secret. Le TP1-a l’utilise pour retrouver le mot de passe encodé avant le déchiffrement AES.`],
[6,`Après avoir signé un fichier avec OpenSSL, quelle commande vérifie la signature avec la clé publique ?`,["<code>openssl dgst -sha256 -verify public.pem -signature sig.bin msg.txt</code>","<code>openssl enc -d -aes-256-cbc -in sig.bin</code>","<code>openssl x509 -in sig.bin -text</code>","<code>openssl rand -verify public.pem</code>"],0,`C’est la commande de vérification du TP1-a : OpenSSL recalcule l’empreinte de <code>msg.txt</code> et la compare à la signature vérifiée avec <code>public.pem</code>.`],
[7,`Dans une ACL Squid, quelle différence entre <code>src</code> et <code>dstdomain</code> ?`,["<code>src</code> désigne l’adresse source du client ; <code>dstdomain</code> le domaine de destination","<code>src</code> désigne le port ; <code>dstdomain</code> le mot de passe","Les deux désignent le fichier journal","<code>src</code> chiffre le trafic ; <code>dstdomain</code> le déchiffre"],0,`Le TP4 distingue les ACL basées sur le client et celles basées sur la destination. On peut autoriser un réseau local tout en bloquant certains domaines.`],
[7,`Dans Squid, que fait <code>http_access deny all</code> placé après les règles d’autorisation ?`,["Il refuse les requêtes qui n’ont pas déjà été autorisées","Il autorise tous les clients sans condition","Il vide le cache","Il désactive les ACL précédentes"],0,`Les règles sont évaluées dans l’ordre. <code>deny all</code> en dernier établit le refus par défaut pour les requêtes qui n’ont correspondu à aucune règle d’autorisation.`],
[7,`À quoi sert principalement <code>cache_mem</code> dans la configuration Squid du TP4 ?`,["À régler la quantité de mémoire utilisée pour les objets en cache","À définir le nombre de mots de passe autorisés","À fixer la taille des clés TLS","À choisir le port d’écoute"],0,`<code>cache_mem</code> règle la quantité de mémoire que Squid peut utiliser pour le cache mémoire ; ce n’est pas la taille totale du cache disque.`],
[5,`Combien de combinaisons pour 6 lettres minuscules (force brute) ?`,["26⁶ = 308 915 776","36⁶ = 2 176 782 336","6²⁶","26×6"],0,`Avec 6 caractères alphanumériques : 36⁶ = 2 176 782 336, soit ~7 fois plus.`],
[5,`Quel mot de passe résiste le mieux ?`,["azerty","Dakar2024","Tr0ub4dor&3-cheval-pile-ciel!","12345678"],2,`Longueur et mélange (majuscules, chiffres, spéciaux) dominent, avec un mot de passe unique par compte.`],
[6,`Générer une clé privée RSA 2048 bits :`,["openssl genrsa -out private.pem 2048","openssl rsa -gen 2048","openssl key -new rsa","openssl rsa -in 2048"],0,`<pre>openssl genrsa -out private.pem 2048</pre>`],
[6,`Extraire la clé publique depuis <code>private.pem</code> :`,["openssl rsa -in private.pem -pubout -out public.pem","openssl pub -in private.pem","openssl rsa -pub private.pem","openssl x509 -pubout"],0,`<pre>openssl rsa -in private.pem -pubout -out public.pem</pre>`],
[6,`Calculer l’empreinte SHA-256 d’un fichier :`,["openssl sha fichier.txt","openssl dgst -sha256 fichier.txt","openssl hash -256 fichier.txt","openssl enc -sha256 fichier.txt"],1,`<pre>openssl dgst -sha256 fichier.txt\nopenssl dgst -sha256 -hmac "cle" fichier.txt   # HMAC</pre>`],
[6,`Chiffrer un fichier en AES-256-CBC avec mot de passe :`,["openssl enc -aes-256-cbc -pbkdf2 -salt -in a.txt -out a.enc","openssl aes -e a.txt","openssl enc -d -aes-256-cbc -in a.txt","openssl encrypt -aes a.txt"],0,`<pre>openssl enc -aes-256-cbc -pbkdf2 -salt -in a.txt -out a.enc\nopenssl enc -d -aes-256-cbc -pbkdf2 -in a.enc -out a.txt</pre>L’option <code>-d</code> déchiffre. Le sel est stocké dans l’en-tête du fichier.`],
[6,`Signer <code>msg.txt</code> avec SHA-256 et la clé privée :`,["openssl dgst -sha256 -sign private.pem -out sig.bin msg.txt","openssl sign msg.txt private.pem","openssl rsa -sign msg.txt","openssl dgst -sha256 -encrypt public.pem msg.txt"],0,`Vérification côté destinataire :<pre>openssl dgst -sha256 -verify public.pem -signature sig.bin msg.txt\n# Verified OK</pre>`],
[6,`Créer un certificat auto-signé valable 1 an :`,["openssl req -x509 -newkey rsa:2048 -nodes -keyout key.pem -out cert.pem -days 365","openssl x509 -new -days 365","openssl cert -self -out cert.pem","openssl genrsa -x509 365"],0,`Ajouter <code>-subj "/C=SN/O=MSIA/CN=localhost"</code> pour éviter les questions. Afficher le contenu :<pre>openssl x509 -in cert.pem -text -noout</pre>`],
[6,`Inspecter le certificat envoyé par un serveur HTTPS :`,["openssl s_client -connect exemple.com:443","openssl x509 -url exemple.com","openssl ssl -show exemple.com","openssl req -view exemple.com"],0,`<pre>openssl s_client -connect exemple.com:443 -showcerts\necho | openssl s_client -connect exemple.com:443 2>/dev/null | openssl x509 -noout -dates -issuer</pre>`],
[7,`Squid est :`,["Un pare-feu noyau","Un serveur proxy/cache HTTP(S), port 3128 par défaut","Un serveur de messagerie","Un annuaire LDAP"],1,`Il se place entre les clients et Internet pour filtrer, authentifier, journaliser et mettre en cache.<pre>sudo apt install squid\nsudo systemctl enable --now squid</pre>`],
[7,`Fichier de configuration principal de Squid :`,["/etc/squid/squid.conf","/etc/squid.xml","/var/log/squid.conf","/usr/bin/squid.cfg"],0,`Vérifier la syntaxe puis recharger sans coupure :<pre>sudo squid -k parse\nsudo squid -k reconfigure</pre>`],
[7,`Autoriser le réseau local 192.168.1.0/24 :`,["acl lan src 192.168.1.0/24\nhttp_access allow lan","allow 192.168.1.0/24","http_allow lan","acl lan dst 192.168.1.0/24"],0,`<pre>acl lan src 192.168.1.0/24\nhttp_access allow lan\nhttp_access deny all</pre>Les <code>http_access</code> sont lues de haut en bas : la première règle qui correspond s’applique.`],
[7,`Bloquer facebook.com pour tous :`,["Règle deny placée <b>avant</b> l’allow du LAN","Règle deny placée après <code>deny all</code>","Ajouter facebook dans cache_dir","Impossible avec Squid"],0,`<pre>acl bad dstdomain .facebook.com .tiktok.com\nhttp_access deny bad\nhttp_access allow lan</pre>Pour une liste : <code>acl bad dstdomain "/etc/squid/blocked.txt"</code>.`],
[7,`Où consulter les requêtes traitées ?`,["/var/log/squid/access.log","/etc/squid/log.conf","/tmp/squid.out","/var/cache/squid.html"],0,`<pre>sudo tail -f /var/log/squid/access.log\n# TCP_MISS/200 = récupéré sur Internet ; TCP_HIT = servi par le cache ; TCP_DENIED/403 = refusé</pre>`],
[7,`Activer l’authentification Basic par mot de passe :`,["auth_param basic program … basic_ncsa_auth + acl auth proxy_auth REQUIRED","auth on","http_login required","password_file seul suffit"],0,`<pre>sudo htpasswd -c /etc/squid/passwords alice\nauth_param basic program /usr/lib/squid/basic_ncsa_auth /etc/squid/passwords\nacl users proxy_auth REQUIRED\nhttp_access allow users</pre>Les mots de passe sont stockés hachés : même idée que dans le cours.`],
[7,`Pour inspecter du HTTPS, Squid pratique du <b>SSL-Bump</b>. C’est en pratique :`,["Un chiffrement plus fort","Un Man In the Middle consenti : Squid présente de faux certificats signés par une CA interne installée chez les clients","Un tunnel SSH","Une suppression de TLS"],1,`<pre>openssl req -new -newkey rsa:2048 -days 365 -nodes -x509 \\\n -keyout squid-ca.pem -out squid-ca.pem -subj "/CN=Squid-CA"\nhttp_port 3128 ssl-bump cert=/etc/squid/squid-ca.pem generate-host-certificates=on dynamic_cert_mem_cache_size=4MB\nsslcrtd_program /usr/lib/squid/security_file_certgen -s /var/lib/ssl_db -M 4MB\nssl_bump peek all\nssl_bump bump all</pre>Initialiser la base : <code>/usr/lib/squid/security_file_certgen -c -s /var/lib/ssl_db -M 4MB</code>. Sans la CA installée dans les navigateurs, alerte de certificat (cf. attaque MITM). À n’utiliser qu’avec information et accord des utilisateurs.`],
[7,`Tester le proxy depuis un client :`,["curl -x http://IP_PROXY:3128 -I http://example.com","ping -p 3128 IP_PROXY","squid -t IP_PROXY","openssl proxy 3128"],0,`Variante : <code>export https_proxy=http://IP_PROXY:3128</code>. Pour le cache : <code>cache_dir ufs /var/spool/squid 100 16 256</code> puis <code>squid -z</code> pour créer les répertoires.`],
[0,`Avec le codage A=0,...,Z=25, quelle formule déchiffre un César de clé K ?`,["D(K,Y)=(Y−K) mod 26","D(K,Y)=(Y+K) mod 26","D(K,Y)=K−Y","D(K,Y)=Y×K mod 26"],0,`Le chiffrement ajoute K modulo 26 ; le déchiffrement soustrait donc K : D(K,Y)=(Y−K) mod 26.`],
[1,`Pour une permutation de transposition utilisant exactement 6 positions, combien de clés différentes peut-on former ?`,["36","120","720","6²⁶"],2,`Une clé est un ordre des 6 positions : il y a 6! = 6×5×4×3×2×1 = 720 permutations possibles.`],
[1,`Dans le protocole du TD4, B reçoit <code>A1=M⊕a</code>, renvoie <code>B1=A1⊕b</code>, puis reçoit <code>A2=B1⊕a</code>. Quelle opération permet à B de retrouver M ?`,["Calculer <code>A2⊕b</code>","Calculer <code>A2⊕a</code>","Calculer <code>A1⊕A2</code>","Hacher B1"],0,`A2=(M⊕a⊕b)⊕a=M⊕b car a⊕a=0. B calcule donc A2⊕b=M. Le TD souligne aussi que l’observation de tous les échanges compromet ce protocole.`],
[1,`Deux blocs chiffrés d’un message ECB sont permutés avant réception. Que se passe-t-il au déchiffrement ?`,["Chaque bloc reste déchiffrable, mais l’ordre des blocs clairs est lui aussi permuté","Le second bloc ne peut plus être déchiffré","La clé devient nécessairement invalide","Les blocs se corrigent automatiquement"],0,`ECB traite chaque bloc séparément. Permuter les blocs chiffrés permute donc les blocs clairs correspondants sans empêcher leur déchiffrement individuel.`],
[1,`Quel énoncé décrit le mieux le mode OFB ?`,["Il transforme le chiffrement par bloc en flot de clé synchronisé, combiné au clair par XOR","Il chiffre chaque bloc indépendamment comme ECB","Il authentifie automatiquement les données comme GCM","Il n’utilise ni clé ni IV"],0,`OFB génère un flot à partir de la clé et de l’IV, puis le combine au texte clair par XOR. La réutilisation d’un même flot avec la même clé et le même IV est dangereuse.`],
[1,`Pourquoi AES-GCM exige-t-il de ne pas réutiliser un nonce avec la même clé ?`,["La réutilisation peut compromettre la confidentialité et l’authenticité des messages","Le nonce est la clé privée RSA","GCM ne peut alors plus déchiffrer aucun fichier","Cela transforme AES en fonction de hachage"],0,`GCM est un mode AEAD et la sécurité de son tag dépend de l’unicité du nonce pour une clé donnée. Il faut suivre la stratégie de génération de nonce recommandée par la bibliothèque utilisée.`],
[2,`Dans un exemple RSA jouet, <code>p=3</code> et <code>q=11</code>. Quelle est la valeur de <code>n</code> ?`,["14","33","20","30"],1,`RSA définit n=p×q. Ici n=3×11=33. Ces paramètres minuscules servent uniquement à illustrer les calculs et ne sont pas sûrs en pratique.`],
[2,`Avec le RSA jouet <code>n=33</code>, <code>e=3</code>, la valeur chiffrée de <code>m=4</code> est <code>c=m^e mod n</code>. Quelle est c ?`,["4","12","31","64"],2,`4³ mod 33 = 64 mod 33 = 31. Les petits nombres RSA sont pédagogiques seulement ; un déploiement utilise des paramètres robustes et un schéma de remplissage sûr.`],
[2,`Pourquoi ne faut-il pas utiliser un petit exemple RSA de TD comme chiffrement réel ?`,["Les paramètres sont factorisables par simple inspection et les schémas réels exigent aussi un padding sûr","RSA ne fonctionne qu’avec des nombres premiers de moins de 10","La clé publique doit rester secrète","Le chiffrement RSA ne produit jamais de texte chiffré"],0,`Les exemples jouets rendent les calculs faisables à la main, mais sont trivialement cassables. En pratique, on utilise une bibliothèque fiable, des tailles de clés adaptées et un schéma de chiffrement RSA moderne comme OAEP.`],
[3,`Pourquoi un HMAC est-il différent d’un simple hash SHA-256 ?`,["HMAC utilise aussi un secret partagé et permet de vérifier l’authenticité du message","HMAC est réversible","HMAC chiffre toujours le message","HMAC n’a pas de clé"],0,`Un hash seul est calculable par tous et ne prouve pas qui a produit le message. HMAC combine le message avec une clé secrète connue des parties.`],
[3,`Une empreinte SHA-256 change après une modification du fichier. Qu’est-ce que cela permet de détecter ?`,["Une différence de contenu entre le fichier vérifié et celui de référence","L’identité certaine de l’auteur","La confidentialité du fichier","La validité du certificat TLS"],0,`Comparer une empreinte de référence avec celle du fichier reçu aide à détecter une modification. Sans canal fiable pour obtenir l’empreinte de référence, un attaquant pourrait remplacer les deux.`],
[4,`Pourquoi un serveur envoie-t-il généralement le certificat serveur et les certificats intermédiaires, mais pas le certificat racine ?`,["La racine est normalement déjà dans le magasin de confiance du client","La racine contient la clé privée du serveur","Le certificat racine est toujours expiré","TLS interdit d’envoyer les certificats intermédiaires"],0,`Le client construit la chaîne jusqu’à une racine déjà approuvée dans son magasin de confiance. La racine n’a généralement pas besoin d’être transmise par le serveur.`],
[4,`À quoi sert principalement l’extension SAN d’un certificat TLS ?`,["À lister les noms d’hôte pour lesquels le certificat est valide","À stocker le mot de passe du serveur","À sélectionner la version de TCP","À chiffrer la clé privée"],0,`Le client vérifie que le nom du site demandé correspond à un nom du Subject Alternative Name. Un certificat valide pour un autre domaine ne suffit pas.`],
[4,`Dans TLS 1.3, à quel moment les messages du serveur qui suivent le Server Hello sont-ils généralement chiffrés ?`,["Après l’établissement des secrets de handshake, notamment les messages Certificate et Finished","Avant le Client Hello","Jamais : TLS 1.3 transmet tout en clair","Uniquement après la requête HTTP"],0,`TLS 1.3 chiffre une plus grande partie du handshake : après le Server Hello et l’établissement des secrets de handshake, les messages suivants du serveur sont protégés.`],
[6,`Quelle commande OpenSSL vérifie un certificat <code>cert.pem</code> avec le fichier d’autorité <code>ca.pem</code> ?`,["<code>openssl verify -CAfile ca.pem cert.pem</code>","<code>openssl dgst -verify ca.pem cert.pem</code>","<code>openssl enc -ca ca.pem cert.pem</code>","<code>openssl req -check ca.pem cert.pem</code>"],0,`<code>openssl verify</code> valide la chaîne du certificat à partir de l’autorité de confiance fournie avec <code>-CAfile</code>.`],
[6,`À quoi sert <code>openssl req -new -key private.pem -out req.csr</code> ?`,["À créer une demande de signature de certificat (CSR) à partir de la clé privée","À vérifier une signature de fichier","À extraire la clé privée d’un certificat","À chiffrer un fichier en AES"],0,`Une CSR contient notamment la clé publique et les informations d’identité demandées. Elle est soumise à une autorité de certification ; elle n’est pas encore un certificat signé.`],
[7,`Après modification de <code>squid.conf</code>, quelle séquence du TP4 vérifie puis applique la configuration ?`,["<code>squid -k parse</code>, puis <code>squid -k reconfigure</code>","<code>squid -z</code> uniquement","<code>openssl verify</code>, puis <code>curl</code>","Supprimer <code>access.log</code>, puis redémarrer le navigateur"],0,`<code>squid -k parse</code> vérifie la syntaxe ; si elle est correcte, <code>squid -k reconfigure</code> recharge la configuration sans redémarrage complet.`],
[7,`Dans les journaux Squid, que signifie généralement le statut <code>TCP_DENIED/403</code> ?`,["La requête a été refusée par une règle d’accès","Le contenu a été servi depuis le cache","Le client a reçu une réponse DNS","Le cache disque a été initialisé"],0,`Le journal <code>access.log</code> indique le résultat de la requête. <code>TCP_DENIED/403</code> correspond à un accès refusé, contrairement à un cache hit ou miss.`],
[7,`Dans <code>http_access allow lan users</code>, comment Squid combine-t-il les deux ACL ?`,["Le client doit correspondre à <code>lan</code> ET à <code>users</code>","Il suffit de correspondre à l’une des deux ACL","La seconde ACL remplace la première","Les ACL sont ignorées dans une règle allow"],0,`Plusieurs ACL placées sur une même règle <code>http_access</code> sont combinées avec ET. Pour autoriser un client, il doit donc appartenir au réseau <code>lan</code> et satisfaire l’ACL d’authentification <code>users</code>.`],
[7,`Si une même ACL <code>site</code> est définie sur plusieurs lignes avec des domaines différents, comment les valeurs sont-elles évaluées ?`,["Une correspondance avec l’une des valeurs suffit (OU)","Toutes les valeurs doivent correspondre (ET)","Seule la dernière ligne est utilisée","La configuration est toujours invalide"],0,`Les valeurs d’une même ACL s’ajoutent et une correspondance avec l’une d’elles suffit. Par exemple, <code>acl site dstdomain .exemple.fr</code> puis <code>acl site dstdomain .exemple.com</code> couvrent les deux domaines.`],
[7,`Que signifie <code>acl Safe_ports port 80 443</code> ?`,["L’ACL correspond aux requêtes visant les ports 80 OU 443","Elle ouvre ces ports sur le pare-feu du serveur","Elle autorise uniquement les clients dont l’adresse finit par 80 ou 443","Elle chiffre les connexions sur ces ports"],0,`L’ACL <code>port</code> teste le port de destination de la requête. La règle de sécurité courante consiste à refuser les ports qui ne sont pas dans la liste, par exemple avec <code>http_access deny !Safe_ports</code>, avant les autorisations générales.`],
[7,`Dans quel ordre placer <code>http_access deny !Safe_ports</code>, <code>http_access allow lan</code> et <code>http_access deny all</code> ?`,["Refus des ports non sûrs, autorisation du LAN, puis refus par défaut","Autorisation du LAN, refus par défaut, puis refus des ports non sûrs","Refus par défaut, autorisation du LAN, puis refus des ports non sûrs","L’ordre n’a aucune importance"],0,`Squid évalue les règles <code>http_access</code> de haut en bas et applique la première règle correspondante. Les contrôles restrictifs doivent précéder l’autorisation générale ; <code>deny all</code> termine la politique par un refus par défaut.`],
[7,`À quoi sert une ACL Squid de type <code>time</code> ?`,["À faire correspondre une plage de jours et d’heures","À mesurer le temps de chargement d’une page","À limiter la durée de vie du cache","À synchroniser l’horloge du proxy"],0,`Une ACL <code>time</code> permet d’appliquer une règle selon un horaire, par exemple <code>acl horaires time MTWHF 08:00-18:00</code>. On peut ensuite la combiner avec une ACL de client dans une règle <code>http_access</code>.`],
[7,`Que vérifie <code>acl ecriture method POST PUT</code> ?`,["Si la méthode HTTP est POST ou PUT","Si l’URL contient les mots POST ou PUT","Si le client utilise les ports 80 ou 443","Si Squid a reçu une réponse du serveur"],0,`Le type d’ACL <code>method</code> compare la méthode HTTP de la requête. Ici, l’ACL correspond aux requêtes POST ou PUT ; elle peut être utilisée dans une règle <code>http_access</code>.`],
[7,`Quelle affirmation décrit <code>url_regex -i</code> ?`,["Il teste une expression régulière sur l’URL, sans tenir compte de la casse","Il teste uniquement l’adresse IP du client","Il vérifie le certificat TLS du site","Il compare l’URL en respectant obligatoirement la casse"],0,`Le type <code>url_regex</code> compare l’URL à une expression régulière ; l’option <code>-i</code> rend la comparaison insensible à la casse. Pour filtrer seulement le chemin, Squid propose aussi <code>urlpath_regex</code>.`],
[7,`Que permet de limiter une ACL <code>maxconn 10</code> associée à une adresse source ?`,["Le nombre de connexions simultanées depuis un client","Le débit total du réseau à 10 Mo/s","Le nombre de domaines autorisés","La durée maximale d’une connexion à 10 secondes"],0,`Une ACL de type <code>maxconn</code> correspond aux clients qui dépassent le nombre configuré de connexions simultanées. Elle est souvent combinée à une ACL <code>src</code> pour appliquer la limite par adresse client.`],
[7,`À quoi correspond <code>acl lan src 192.168.10.0/24</code> ?`,["Aux adresses sources de 192.168.10.0 à 192.168.10.255","Aux domaines dont le nom contient 192.168.10","Aux ports TCP de 0 à 24","À une plage d’adresses de destination uniquement"],0,`<code>src</code> teste l’adresse IP source. Le suffixe <code>/24</code> indique un préfixe réseau : cette plage comprend les adresses de 192.168.10.0 à 192.168.10.255.`],
[7,`Comment charger dans une ACL <code>dstdomain</code> une liste de domaines enregistrée dans un fichier ?`,['<code>acl interdits dstdomain "/etc/squid/domaines.txt"</code>','<code>acl interdits src "/etc/squid/domaines.txt"</code>',"<code>http_access include /etc/squid/domaines.txt</code>","<code>cache_dir /etc/squid/domaines.txt</code>"],0,`Une ACL peut lire ses valeurs dans un fichier en plaçant son chemin entre guillemets après le type d’ACL. Ici, le fichier contient les domaines à faire correspondre avec <code>dstdomain</code>.`],
[1,`Dans le TP AES-ECB, pourquoi deux blocs de texte clair identiques donnent-ils le même bloc chiffré ?`,["ECB chiffre chaque bloc séparément avec la même clé, sans IV","ECB réutilise automatiquement la clé privée","Le texte est d’abord compressé","Chaque bloc est chiffré avec un mot de passe différent"],0,`En mode ECB, chaque bloc est traité indépendamment. Les blocs clairs identiques produisent donc des blocs chiffrés identiques, ce qui révèle des motifs et rend ECB inadapté à de nombreux usages.`],
[1,`En AES-CBC, quel est le rôle de l’IV ?`,["Il est combiné au premier bloc clair avant le chiffrement pour varier le résultat","Il remplace la clé secrète","Il permet de vérifier l’identité de l’émetteur","Il sert uniquement à compléter le dernier bloc"],0,`CBC combine le premier bloc clair avec un vecteur d’initialisation avant le chiffrement, puis chaîne les blocs suivants. L’IV n’est pas secret, mais il doit être généré correctement et ne pas être réutilisé de façon inappropriée avec la même clé.`],
[1,`Pourquoi faut-il ajouter un padding avant de chiffrer avec AES en mode ECB ou CBC ?`,["Ces modes traitent des blocs de taille fixe et le dernier bloc peut être incomplet","Le padding choisit la clé AES","Il transforme AES en chiffrement asymétrique","Il permet de supprimer l’IV"],0,`AES traite des blocs de 16 octets. Si le texte ne remplit pas un nombre entier de blocs, un padding tel que PKCS#7 complète le dernier bloc ; il faut ensuite le retirer après déchiffrement.`],
[1,`Quelles longueurs de clé AES sont standard ?`,["128, 192 ou 256 bits","64, 128 ou 512 bits","256 bits uniquement","1024 ou 2048 bits"],0,`AES accepte des clés de 128, 192 ou 256 bits. La taille du bloc AES reste de 128 bits, quelle que soit la taille de la clé.`],
[5,`Quelle différence y a-t-il entre une attaque par dictionnaire et une force brute ?`,["Le dictionnaire teste des candidats probables ; la force brute parcourt les combinaisons d’un alphabet donné","Le dictionnaire teste des clés publiques ; la force brute teste des certificats","Ce sont deux noms pour la même méthode","La force brute ne teste qu’un mot de passe par utilisateur"],0,`L’attaque par dictionnaire essaie une liste de mots ou de variantes fréquentes. La force brute explore systématiquement les combinaisons possibles ; son coût croît rapidement avec la longueur et la taille de l’alphabet.`],
[5,`Pourquoi un sel unique est-il ajouté avant le hachage de chaque mot de passe ?`,["Pour empêcher la réutilisation directe de tables précalculées et faire différer les empreintes de mots identiques","Pour rendre le hash réversible","Pour cacher le nom de l’algorithme","Pour éviter d’avoir à vérifier le mot de passe lors de la connexion"],0,`Le sel est aléatoire, propre à chaque mot de passe et stocké avec l’empreinte. Deux utilisateurs ayant le même mot de passe obtiennent ainsi des empreintes différentes ; le sel n’a pas besoin d’être secret.`],
[4,`Dans une capture TLS, quel message contient notamment les versions et suites cryptographiques proposées par le client ?`,["Client Hello","Server Finished","Certificate Verify","Application Data"],0,`Le Client Hello lance le handshake et annonce les paramètres pris en charge, notamment les versions TLS et les suites cryptographiques proposées. Le serveur choisit ensuite les paramètres de la connexion.`],
[4,`À quoi sert l’extension SNI dans le Client Hello TLS ?`,["À indiquer le nom du serveur demandé afin qu’il puisse choisir le bon certificat","À transmettre le mot de passe du navigateur","À chiffrer le certificat serveur","À choisir le port TCP du proxy"],0,`Le SNI (Server Name Indication) indique le nom d’hôte visé au début de la négociation TLS. Un serveur hébergeant plusieurs sites peut ainsi sélectionner le certificat correspondant.`],
[4,`Dans Wireshark, à quoi sert le fichier défini par <code>SSLKEYLOGFILE</code> dans le TP ?`,["À fournir les secrets de session TLS permettant de déchiffrer une capture de test","À remplacer le certificat du serveur","À enregistrer les mots de passe des sites visités","À générer les clés privées RSA du navigateur"],0,`Un navigateur compatible peut écrire les secrets de session dans ce fichier. Wireshark peut les utiliser pour déchiffrer le trafic correspondant ; il faut protéger le fichier, qui donne accès au contenu des sessions capturées.`],
[4,`Pourquoi le certificat racine d’une chaîne TLS n’est-il généralement pas envoyé par le serveur ?`,["Le client possède normalement déjà la racine dans son magasin de confiance","La racine est toujours chiffrée dans le Client Hello","La racine ne contient pas de clé publique","TLS interdit les certificats racines"],0,`Le serveur transmet normalement son certificat et les certificats intermédiaires nécessaires. Le client vérifie la chaîne jusqu’à une autorité racine déjà approuvée dans son magasin de confiance.`],
[7,`Quel est le rôle de SquidGuard dans l’architecture présentée au TP4 ?`,["Un redirecteur associé à Squid pour appliquer du filtrage d’URL","Un outil qui remplace TLS par SSH","Un serveur de certificats racines","Un mode de cache mémoire de Squid"],0,`Squid fournit le service proxy et les règles d’accès ; SquidGuard peut être associé comme redirecteur pour appliquer des politiques de filtrage d’URL, notamment à partir de listes de domaines.`],
[0,`Dans le TD1, avec A=0,...,Z=25, quelle formule chiffre une lettre X par César avec la clé K ?`,[`E(K,X)=(X+K) mod 26`,`E(K,X)=(X−K) mod 26`,`E(K,X)=X×K`,`E(K,X)=K−X`],0,`Le TD1 utilise le décalage modulo 26 : on convertit X en entier, on ajoute K, puis on revient à une lettre avec le reste modulo 26.`,0],
[0,`Pour chiffrer <code>WELCOMETOUASZ</code> par César avec K=5, combien de substitutions de lettres faut-il effectuer ?`,[`Une seule`,`5`,`13`,`Une par lettre, donc 13`],3,`La formule est appliquée une fois à chacune des 13 lettres du message. Le nombre d’essais de clé éventuels ne change pas cette longueur.`,0],
[0,`Dans le chiffrement mono-alphabétique du TD1, combien de clés de substitution possibles existe-t-il pour les 26 lettres ?`,[`26²`,`26!`,`26`,`25!`],1,`Une clé est une permutation des 26 lettres, tirées sans remise : il y a donc 26! clés possibles.`,0],
[0,`Une clé de transposition comporte les six positions <code>[1,2,3,4,5,6]</code>. Combien de permutations différentes peut-elle représenter ?`,[`36`,`120`,`720`,`6²⁶`],2,`L’ordre des six positions peut être choisi de 6! façons, soit 720 clés possibles.`,0],
[0,`Avec le chiffrement de Vigenère du TD1 et la clé <code>MASTER</code>, comment traite-t-on un message plus long que la clé ?`,[`On répète la clé au-dessus du message`,`On complète la clé avec des espaces uniquement`,`On chiffre seulement les six premières lettres`,`On remplace la clé par son inverse après six lettres`],0,`Vigenère aligne une clé répétée sur le message et applique les décalages correspondants.`,0],
[0,`Que permet la clé inverse d’une transposition ?`,[`Retrouver l’ordre initial des positions et donc reconstituer le message`,`Calculer une empreinte du message`,`Créer une nouvelle clé publique`,`Ajouter un bourrage au dernier bloc`],0,`La clé inverse annule la permutation appliquée au chiffrement : elle replace les caractères dans leur ordre d’origine.`,0],
[1,`Dans l’exercice ECB du TD2, que fait le chiffrement à chaque bloc de 4 bits ?`,[`Il applique séparément la transformation définie à chacun des blocs`,`Il combine chaque bloc avec le précédent`,`Il utilise un IV différent pour chaque bloc`,`Il chiffre le message entier comme un bloc unique`],0,`ECB traite chaque bloc indépendamment. Dans l’exercice, les blocs ont 4 bits et la transformation donnée est appliquée à chacun d’eux.`,1],
[1,`Le message binaire du TD2 a 14 bits et les blocs font 4 bits. Combien de zéros faut-il ajouter à droite pour obtenir des blocs complets ?`,[`1`,`2`,`3`,`4`],1,`14 bits donnent trois blocs complets et deux bits restants. Il faut ajouter deux zéros pour former le quatrième bloc de 4 bits.`,1],
[1,`En ECB, si deux blocs clairs sont identiques et chiffrés avec la même clé, que constate-t-on ?`,[`Les blocs chiffrés sont identiques`,`Le second bloc est toujours nul`,`Les blocs chiffrés sont indépendants et aléatoires`,`Le premier bloc révèle la clé`],0,`Comme chaque bloc est traité séparément par la même transformation, des blocs clairs identiques produisent des blocs chiffrés identiques.`,1],
[1,`Dans l’exercice CBC du TD2, par quoi le premier bloc clair est-il combiné avant chiffrement ?`,[`Le vecteur d’initialisation IV`,`Le dernier bloc du message`,`La clé inverse`,`Le nombre de blocs`],0,`CBC combine le premier bloc clair avec l’IV. Chaque bloc suivant est combiné avec le bloc chiffré précédent avant application de la transformation.`,1],
[1,`En CBC, que peut provoquer la permutation de blocs chiffrés avant déchiffrement ?`,[`Le déchiffrement reste possible, mais les blocs clairs peuvent être altérés et dépendre du bloc précédent`,`Tous les blocs clairs sont simplement permutés sans autre effet`,`La clé devient publique`,`Le message se corrige automatiquement`],0,`En CBC, le déchiffrement d’un bloc dépend aussi du bloc chiffré précédent. Réordonner les blocs peut donc altérer plusieurs blocs clairs, contrairement au traitement indépendant d’ECB.`,1],
[1,`Dans la question sur l’effet d’avalanche du TD2, quel ordre de grandeur de bits clairs devient faux si environ 50 % du bloc est affecté ?`,[`Environ 1 %`,`Environ 25 %`,`Environ 50 %`,`100 % exactement`],2,`L’énoncé définit l’effet d’avalanche comme une proportion moyenne d’environ 50 % des bits récupérés affectés lorsqu’un bit d’entrée change. C’est une moyenne, pas une garantie exacte pour chaque bloc.`,1],
[2,`Dans Needham-Schroeder du TD3, à quoi servent principalement les valeurs <code>Na</code> et <code>Nb</code> ?`,[`À apporter des défis frais permettant de lier les réponses à l’échange`,`À remplacer les clés publiques`,`À hacher les identités`,`À compresser les messages`],0,`Les nonces sont des valeurs fraîches. Le retour de la valeur attendue permet de vérifier que la réponse correspond à l’échange en cours et limite les rejeux.`,2],
[2,`A envoie simplement <code>A,s</code> à B, comme dans le protocole 1 du TD3. Le secret s est-il protégé ?`,[`Non, il est envoyé en clair`,`Oui, car le nom A est joint`,`Oui, car tout message réseau est chiffré`,`Seulement si s est un nonce`],0,`Le protocole ne chiffre ni ne masque s : toute personne observant le message peut le lire. Il ne prouve pas non plus à lui seul l’identité de l’émetteur.`,2],
[2,`Dans le protocole 2 du TD3, A envoie <code>{A,s}Kb</code>, où Kb est la clé publique de B. Quelle propriété cela apporte-t-il principalement ?`,[`La confidentialité vis-à-vis des personnes qui ne possèdent pas la clé privée de B`,`La preuve que le message vient de A`,`La fraîcheur du message`,`La non-répudiation de B`],0,`Le chiffrement avec la clé publique de B permet à son détenteur de clé privée de lire le contenu. Il ne prouve pas que A a créé le message, car la clé publique est accessible à tous.`,2],
[2,`A signe <code>s</code> avec sa clé privée puis envoie la signature à B. Quelle propriété la vérification avec la clé publique de A peut-elle apporter ?`,[`Une preuve d’origine et l’intégrité du contenu signé`,`La confidentialité de s`,`La fraîcheur automatique du message`,`Le chiffrement de la connexion`],0,`Une signature vérifiable avec la clé publique de A permet de vérifier que le contenu signé n’a pas été modifié et qu’il a été signé par le détenteur de la clé privée correspondante. Elle ne chiffre pas le contenu et n’assure pas à elle seule sa fraîcheur.`,2],
[2,`Un protocole du TD3 ne contient ni nonce, ni horodatage, ni autre mécanisme de fraîcheur. Quel risque faut-il considérer ?`,[`Un attaquant peut rejouer un ancien message valide`,`Le message devient automatiquement confidentiel`,`La clé publique change à chaque paquet`,`Le hachage devient réversible`],0,`Sans mécanisme de fraîcheur ni état anti-rejeu, un message ancien peut parfois être accepté de nouveau. La présence d’un chiffrement ne suffit pas à empêcher le rejeu.`,2],
[2,`Un message est chiffré avec la clé publique de B, puis signé par A. Quel ordre de vérification convient à B ?`,[`Vérifier la signature avec la clé publique de A et déchiffrer avec la clé privée de B`,`Vérifier avec la clé privée de B et déchiffrer avec la clé publique de A`,`Déchiffrer avec la clé publique de B et signer à nouveau`,`Utiliser la clé privée de A pour les deux opérations`],0,`La clé privée de B sert à déchiffrer ce qui a été chiffré pour B. La clé publique de A sert à vérifier la signature produite avec la clé privée de A.`,2],
[3,`Dans Diffie-Hellman, A et B publient <code>g^a mod p</code> et <code>g^b mod p</code>. Quelle valeur commune calculent-ils ?`,[`g^(ab) mod p`,`g^(a+b) mod p`,`a+b mod p`,`p^(a+b) mod g`],0,`A calcule (g^b)^a mod p et B calcule (g^a)^b mod p : les deux obtiennent g^(ab) mod p.`,3],
[3,`Avec les valeurs du TD4 <code>g=5</code>, <code>p=13</code>, <code>a=3</code>, <code>b=5</code>, quelle clé partagée obtient-on ?`,[`5`,`8`,`10`,`12`],1,`A publie 5³ mod 13 = 8 ; B publie 5⁵ mod 13 = 5. La valeur commune est 5¹⁵ mod 13 = 8.`,3],
[3,`Quel problème mathématique rend difficile la récupération de a à partir de <code>A=g^a mod p</code> dans Diffie-Hellman ?`,[`Le logarithme discret`,`La factorisation d’un hash`,`La recherche d’une collision`,`L’inversion d’une permutation de lettres`],0,`Retrouver l’exposant a à partir de g, p et A est le problème du logarithme discret, cité dans le TD4.`,3],
[3,`Pourquoi Diffie-Hellman sans authentification ne protège-t-il pas contre un homme du milieu ?`,[`L’attaquant peut remplacer les valeurs publiques et établir une clé distincte avec chaque partie`,`Les exposants secrets sont transmis en clair`,`La clé partagée est toujours égale à p`,`Diffie-Hellman n’utilise aucun calcul modulaire`],0,`Un attaquant actif peut intercepter les valeurs publiques et les remplacer. Il négocie alors une clé avec A et une autre avec B, sans que les deux parties partagent directement la même clé.`,3],
[3,`Dans le protocole XOR du TD4, A envoie <code>A1=M⊕a</code>, B répond <code>B1=A1⊕b</code>, puis A envoie <code>A2=B1⊕a</code>. Quelle opération B effectue-t-il pour retrouver M ?`,[`A2⊕b`,`A2⊕a`,`A1⊕A2`,`B1⊕a`],0,`Comme a⊕a=0, A2=M⊕b. B annule alors b en calculant A2⊕b et retrouve M.`,3],
[3,`Dans ce protocole XOR, un observateur connaît A1, B1 et A2. Peut-il retrouver M ?`,[`Oui : b=A1⊕B1, puis M=A2⊕b`,`Non, car a et b ne sont jamais réutilisés`,`Oui, en calculant A1⊕A2 uniquement`,`Non, car XOR est une fonction de hachage`],0,`B1=A1⊕b, donc A1⊕B1=b. Puis A2⊕b=M. L’observateur qui voit tous les échanges peut donc retrouver le message, comme demandé dans l’exercice.`,3],
[3,`B envoie un code confidentiel à A avec une clé publique/privée. Quelle clé doit protéger la confidentialité du message pour A ?`,[`La clé publique de A, que seule la clé privée de A permet de déchiffrer`,`La clé publique de B`,`La clé privée de A, distribuée à tous`,`La clé privée de B`],0,`Pour que seul A puisse lire le message, B le chiffre avec la clé publique de A. A le déchiffre avec sa clé privée, qu’il ne partage pas.`,3],
[1,`Une clé de transposition permute 28 positions distinctes. Combien de clés différentes existe-t-il ?`,[`28²`,`28!`,`2²⁸`,`28×26`],1,`Chaque clé est une permutation des 28 positions : il y en a 28! possibles.`],
[1,`Une clé de Vigenère comporte 8 lettres choisies dans l’alphabet de 26 lettres. Combien de clés sont possibles ?`,[`8!`,`26⁸`,`8²⁶`,`26×8`],1,`Chaque position peut contenir l’une des 26 lettres, indépendamment des autres : le nombre de clés est 26⁸.`],
[3,`A envoie un message m avec son empreinte H(m), où H est publique. Un attaquant peut modifier m et recalculer l’empreinte. Quelle propriété est alors garantie contre cet attaquant ?`,[`L’authentification de A`,`La confidentialité de m`,`Aucune intégrité fiable contre une modification active`,`La fraîcheur du message`],2,`Un hash public permet de détecter une modification si l’empreinte de référence est fiable, mais un attaquant peut remplacer à la fois m et H(m). Une signature ou un MAC est nécessaire pour protéger l’intégrité contre une modification active.`],
[2,`A chiffre la concaténation de m et H(m) avec la clé publique de B. Quel service cette opération apporte-t-elle à elle seule ?`,[`La confidentialité, mais pas une intégrité fiable ni l’authentification de A`,`L’authentification de A uniquement`,`La confidentialité et la non-répudiation`,`La fraîcheur et le contrôle d’accès`],0,`Seul le détenteur de la clé privée de B peut normalement lire le contenu. Comme H est publique, un attaquant peut modifier m et recalculer son empreinte avant chiffrement ; cette construction ne prouve pas non plus qui a envoyé le message.`],
[3,`A chiffre m avec une clé Kab partagée avec B, puis signe avec sa clé privée l’empreinte de m et du texte chiffré. Sous quelles hypothèses obtient-on confidentialité, intégrité et authentification ?`,[`Kab reste secrète entre A et B et la clé publique de A est authentique`,`La clé publique de B est gardée secrète`,`Le message contient seulement un hash public`,`La signature est chiffrée avec la clé publique de A`],0,`Le chiffrement avec Kab protège la confidentialité. La signature vérifiée avec la clé publique authentique de A protège l’origine et l’intégrité des données signées. Sans nonce ni autre mécanisme, cela ne garantit pas la fraîcheur.`],
[3,`Pour authentifier efficacement un lot ordonné de cinq messages, sans devoir les vérifier séparément, que peut faire A ?`,[`Signer H(m1||m2||m3||m4||m5) avec sa clé privée`,`Chiffrer chaque message avec la clé publique de B`,`Envoyer uniquement H(m1), sans signature`,`Signer seulement le premier message`],0,`Une signature sur l’empreinte de la concaténation authentifie le lot comme un ensemble ordonné avec une seule opération de signature. Il faut une représentation non ambiguë des frontières entre messages.`]
];
var F=`<div class="fiche"><h3>OpenSSL – commandes essentielles</h3>
<pre># Aléatoire / mot de passe haché
openssl rand -hex 16
openssl passwd -6 "monmdp"
# Symétrique (AES)
openssl enc -aes-256-cbc -pbkdf2 -salt -in clair.txt -out chiffre.enc
openssl enc -d -aes-256-cbc -pbkdf2 -in chiffre.enc -out clair.txt
# Asymétrique RSA
openssl genrsa -out private.pem 2048
openssl rsa -in private.pem -pubout -out public.pem
openssl pkeyutl -encrypt -pubin -inkey public.pem -in msg.txt -out msg.enc
openssl pkeyutl -decrypt -inkey private.pem -in msg.enc -out msg.dec
# Courbes elliptiques
openssl ecparam -name prime256v1 -genkey -noout -out ec.pem
# Hachage, HMAC, signature
openssl dgst -sha256 msg.txt
openssl dgst -sha256 -hmac "cle" msg.txt
openssl dgst -sha256 -sign private.pem -out sig.bin msg.txt
openssl dgst -sha256 -verify public.pem -signature sig.bin msg.txt
# Diffie-Hellman
openssl dhparam -out dh.pem 2048
# Certificats
openssl req -new -key private.pem -out req.csr -subj "/CN=monsite.sn"
openssl req -x509 -newkey rsa:2048 -nodes -keyout key.pem -out cert.pem -days 365
openssl x509 -in cert.pem -text -noout
openssl verify -CAfile ca.pem cert.pem
openssl s_client -connect exemple.com:443</pre>
<h3>Squid – configuration type</h3>
<pre>http_port 3128
acl lan src 192.168.1.0/24
acl bad dstdomain .facebook.com
acl users proxy_auth REQUIRED
http_access deny bad
http_access allow lan users
http_access deny all
cache_dir ufs /var/spool/squid 100 16 256
access_log /var/log/squid/access.log</pre>
<pre>sudo squid -z          # créer le cache
sudo squid -k parse    # tester la config
sudo squid -k reconfigure
sudo systemctl restart squid</pre>
<h3>Rappels de cours</h3>
<pre>César : E(K,X) = (X+K) mod 26      Clés symétriques : n(n-1)/2
XOR : A ⊕ K ⊕ K = A               DH : K = g^(ab) mod p
Signature : s = E(PrivA, H(m))     Vérif : D(PubA, s) = H(m)
Hybride : clé symétrique échangée par asymétrique (TLS)</pre></div>`;
var app=document.getElementById("app"),st={},store=null,questionCount=10;
try{store=window.localStorage}catch(e){}
function shuf(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=a[i];a[i]=a[j];a[j]=t}return a}
function best(){try{return JSON.parse(store.getItem("cq")||"{}")}catch(e){return{}}}
function home(){
 setNav("nq");var b=best();
 var h=`<p class="lead">Quiz de révision : cryptographie, OpenSSL et Squid. Chaque réponse est expliquée. ${Q.length} questions.</p><div class="count-control"><label for="question-count">Nombre de questions</label><input id="question-count" type="number" min="1" max="${Q.length}" step="1" value="${questionCount}"></div><div class="grid">`;
 h+=`<button class="cat" data-c="-1"><b>Toutes les catégories</b><span>${Q.length} questions mélangées${b["-1"]!=null?" · meilleur : "+b["-1"]+"%":""}</span></button>`;
 CATS.forEach(function(n,i){var c=Q.filter(function(q){return q[0]==i}).length;h+=`<button class="cat" data-c="${i}"><b>${n}</b><span>${c} questions${b[i]!=null?" · meilleur : "+b[i]+"%":""}</span></button>`});
 h+=`</div><h2 class="section-title">Quiz par TD</h2><div class="grid">`;
 TD_NAMES.forEach(function(n,i){var c=Q.filter(function(q){return q[5]==i}).length;h+=`<button class="cat" data-td="${i}"><b>${n}</b><span>${c} questions${b["td"+i]!=null?" · meilleur : "+b["td"+i]+"%":""}</span></button>`});
 app.innerHTML=h+"</div>";
 document.getElementById("question-count").onchange=function(){var value=parseInt(this.value,10);if(Number.isFinite(value)){questionCount=Math.max(1,Math.min(Q.length,value));this.value=questionCount}};
 app.querySelectorAll(".cat").forEach(function(e){e.onclick=function(){start(+e.dataset.c)}});
 app.querySelectorAll("[data-td]").forEach(function(e){e.onclick=function(){start(-1,+e.dataset.td)}});
}
function start(c,td,count){
 var l=Q.filter(function(q){return (c<0||q[0]==c)&&(td==null||q[5]==td)});
 var requested=count==null?parseInt(document.getElementById("question-count").value,10):count;
 if(!Number.isFinite(requested)||requested<1)requested=questionCount;
 requested=Math.max(1,Math.min(Q.length,requested));questionCount=requested;
 var selected=shuf(l).slice(0,Math.min(requested,l.length));
 st={c:c,td:td,count:requested,i:0,s:0,w:[],by:{},list:selected.map(function(q){var o=q[2].map(function(t,k){return{t:t,k:k}});return{c:q[0],q:q[1],o:shuf(o),a:q[3],e:q[4]}})};
 show();
}
function show(){
 var q=st.list[st.i],n=st.list.length,h=`<div class="meta"><span>Question ${st.i+1}/${n}</span><span>Score : ${st.s}</span></div><div class="bar"><i style="width:${st.i/n*100}%"></i></div><div class="card"><span class="tag">${CATS[q.c]}</span><p class="q">${q.q}</p>`;
 q.o.forEach(function(o,i){h+=`<button class="opt" data-i="${i}">${o.t.replace(/\n/g,"<br>").replace(/^(openssl|squid|acl|curl|auth_param)(.*)$/,"<code>$1$2</code>")}</button>`});
 app.innerHTML=h+`<div id="ex"></div></div>`;
 app.querySelectorAll(".opt").forEach(function(b){b.onclick=function(){answer(+b.dataset.i)}});
}
function answer(i){
 var q=st.list[st.i],ok=q.o[i].k==q.a,bs=app.querySelectorAll(".opt");
 bs.forEach(function(b,j){b.disabled=true;if(q.o[j].k==q.a)b.classList.add("ok");else if(j==i)b.classList.add("ko")});
 var by=st.by[q.c]||(st.by[q.c]=[0,0]);by[1]++;
 if(ok){st.s++;by[0]++}else st.w.push(q);
 var last=st.i==st.list.length-1;
 document.getElementById("ex").innerHTML=`<div class="exp ${ok?"g":"b"}"><b>${ok?"Bonne réponse !":"Raté."}</b> ${q.e}</div><button class="pri" id="nx">${last?"Voir le résultat":"Question suivante"}</button>`;
 document.getElementById("nx").onclick=function(){last?end():(st.i++,show())};
 document.getElementById("nx").focus();
}
function end(){
 var n=st.list.length,p=Math.round(st.s/n*100),b=best(),bestKey=st.td==null?st.c:"td"+st.td;
 if(b[bestKey]==null||p>b[bestKey]){b[bestKey]=p;try{store.setItem("cq",JSON.stringify(b))}catch(e){}}
 var m=p>=80?"Excellent, tu maîtrises le sujet.":p>=50?"Pas mal, relis les explications des erreurs.":"À retravailler : consulte les fiches puis recommence.";
 var h=`<div class="card"><p class="score">${st.s}/${n}</p><p>${p}% — ${m}</p>`;
 Object.keys(st.by).forEach(function(k){h+=`<div class="row"><span>${CATS[k]}</span><b>${st.by[k][0]}/${st.by[k][1]}</b></div>`});
 h+=`<button class="pri" id="rp">Rejouer</button> <button class="ghost" id="hm">Menu</button>`;
 if(st.w.length)h+=`<h3>À revoir (${st.w.length})</h3>`+st.w.map(function(q){return`<details><summary>${q.q.replace(/<[^>]+>/g,"")}</summary><p><b>Réponse :</b> ${q.o.filter(function(o){return o.k==q.a})[0].t.replace(/\n/g," ")}</p><div>${q.e}</div></details>`}).join("");
 app.innerHTML=h+"</div>";
 document.getElementById("rp").onclick=function(){start(st.c,st.td,st.count)};document.getElementById("hm").onclick=home;
}
function fiches(){setNav("nf");app.innerHTML=`<p class="lead">Aide-mémoire pour la pratique et le cours.</p>`+F}
function setNav(id){document.getElementById("nq").className=id=="nq"?"on":"";document.getElementById("nf").className=id=="nf"?"on":""}
document.getElementById("nq").onclick=home;document.getElementById("nf").onclick=fiches;
document.getElementById("th").onclick=function(){var r=document.documentElement,d=r.dataset.theme=="dark"||(!r.dataset.theme&&matchMedia("(prefers-color-scheme:dark)").matches);r.dataset.theme=d?"light":"dark"};
home();
